# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Invoices::OperationLock do
  # "Take `pg_advisory_xact_lock` keyed on (company_id, invoice_id) in the invoice transaction."
  # A nil part would collapse many saves onto one shared key, so the key builder refuses it.
  it "refuses to lock when company_id or invoice_id is missing" do
    connection = ActiveRecord::Base.connection

    expect { described_class.acquire!(connection, company_id: 1, invoice_id: nil) }.to raise_error(ArgumentError)
    expect { described_class.acquire!(connection, company_id: nil, invoice_id: 10) }.to raise_error(ArgumentError)
  end
end

RSpec.describe Invoices::OperationLock, committed_data: true do
  # "Take `pg_advisory_xact_lock` keyed on (company_id, invoice_id) in the invoice transaction."
  it "does not make a save in one company wait on another company's lock for the same invoice id" do
    holder_pids = Queue.new
    release = Queue.new
    holder = committed_data_thread(holder_pids) do
      ActiveRecord::Base.transaction do
        described_class.acquire!(ActiveRecord::Base.connection, company_id: 1, invoice_id: 10)
        release.pop
      end
    end
    holder_pid = holder_pids.pop

    other_company_pids = Queue.new
    other_company = committed_data_thread(other_company_pids) do
      ActiveRecord::Base.transaction do
        described_class.acquire!(ActiveRecord::Base.connection, company_id: 2, invoice_id: 10)
      end
    end
    other_company_pid = other_company_pids.pop

    expect(blocked_by?(other_company_pid, holder_pid, within: 1)).to be(false)
    expect(other_company.join(5)).to be_truthy

    same_company_pids = Queue.new
    same_company = committed_data_thread(same_company_pids) do
      ActiveRecord::Base.transaction do
        described_class.acquire!(ActiveRecord::Base.connection, company_id: 1, invoice_id: 10)
      end
    end
    expect(blocked_by?(same_company_pids.pop, holder_pid)).to be(true)
  ensure
    release&.push(true)
    holder&.join
    same_company&.join
  end
end
